package com.kovian.finance.asset.api; import com.kovian.finance.asset.domain.*; import com.kovian.finance.asset.repository.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*; @RestController @RequestMapping("/api/v1/assets") public class AssetController {final FinancialAssetRepository repo; AssetController(FinancialAssetRepository r){repo=r;} record Request(UUID ownerId,String name,String assetType,BigDecimal acquisitionValue,BigDecimal currentValue,AssetLiquidity liquidity){} @PostMapping public FinancialAsset create(@RequestBody Request r){return repo.save(new FinancialAsset(r.ownerId(),r.name(),r.assetType(),r.acquisitionValue(),r.currentValue(),r.liquidity()));} @GetMapping public List<FinancialAsset> list(@RequestParam UUID ownerId){return repo.findByOwnerIdAndActiveTrue(ownerId);} @PatchMapping("/{id}/value") @Transactional public void update(@PathVariable UUID id,@RequestParam UUID ownerId,@RequestBody BigDecimal value){repo.findById(id).filter(a->a.getOwnerId().equals(ownerId)).orElseThrow().updateValue(value);}}